import math

def is_power_of_two(n):
    """Checks if a positive integer n is a power of two."""
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

def find_k(n_val):
    """Finds k such that 2^k = n_val."""
    if n_val <= 0 or not is_power_of_two(n_val):
        return None
    return n_val.bit_length() - 1

