def solve():
    solutions = []
    for n in range(2, 15):
        for x in range(n + 1, 200):
            val = x**n + x - 2
            if val > 0:
                k = val.bit_length() - 1
                if (1 << k) == val:
                    solutions.append((x, n, k))
    return solutions

print(solve())

